9547c895a2f9b04f2abdb673d0942f7b25439508e64aebed5039dc7475b41","q119":"c9554d80a8b7bcdbed09764f54f3c01ad88b8db6b614d175625f033504cc26ca","q120":"29c2b9929e0165ea9779e16a07c03c165bb7903fd5f573fe374e572cfc4c45e7"},"instrumentId":"ipip-neo-120-johnson-2014","formVersion":"johnson-2014-table1-v1","scoringVersion":"ipip-neo-120-raw-v1","presentationVersion":"trajectas-personality-labels-v1","itemsetSha256":"0a1c55b136a3a6021cfaeb210931b61d19f4e0d5ced7787c6daf3228cfdd50e6","activationReady":false,"rows":{"content_sources":[{"id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","name":"IPIP-NEO-120 (Johnson, 2014)","slug":"ipip-neo-120-johnson-2014","notes":"Johnson, J. A. (2014). Measuring thirty facets of the Five Factor Model with a 120-item public domain inventory. Journal of Research in Personality, 51, 78-89. https://doi.org/10.1016/j.jrp.2014.05.003. Items and item numbers: publication Table 1. Key directions cross-checked against https://ipip.ori.org/30FacetNEO-PI-RItems.htm, captured 2026-10-29. Item 58 retains the publication''s ''right or wrong''; the web key uses ''right and wrong''. IPIP items/scales/inventories are public domain: https://ipip.ori.org/newPermission.htm. Descriptive library text is a Trajectas preparation draft, not a published interpretive manual or norms. No reference distribution is loaded."}],"response_formats":[{"id":"4ee8ab21-f6b6-5e77-a8b4-f0b5f243ed2d","name":"IPIP-NEO-120 accuracy 1-5 (Johnson 2014)","type":"likert","config":{"points":5,"minValue":1,"maxValue":5,"anchors":{"1":"Very Inaccurate","2":"Moderately Inaccurate","3":"Neither Inaccurate nor Accurate","4":"Moderately Accurate","5":"Very Accurate"}},"is_active":false}],"dimensions":[{"id":"8cd76c06-e099-51f7-a0fb-7848357a3417","slug":"ipip-neo-120-johnson-2014-n-neuroticism","name":"Emotional Reactivity","description":"N — Typical frequency and intensity of distress, emotional reactivity and difficulty coping with pressure.","definition":"Typical frequency and intensity of distress, emotional reactivity and difficulty coping with pressure.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Usually remains emotionally steady.\nExperiences fewer worries or frustrations.\nRecovers composure relatively readily.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Experiences distress or worry more readily.\nReacts more strongly to setbacks.\nCan feel overwhelmed under pressure.","anchor_low":"Usually remains emotionally steady.","anchor_high":"Experiences distress or worry more readily.","strength_commentary":"Lower reactivity can support steadiness; greater sensitivity may bring concerns to attention. Neither end establishes coping skill, mental health status or leadership effectiveness.","development_suggestion":"Identify situations that intensify emotional reactions and the responses that help you act constructively.","display_order":0,"is_scored":true},{"id":"f3531906-ff75-5f40-a7eb-65634f819ac1","slug":"ipip-neo-120-johnson-2014-e-extraversion","name":"Extraversion","description":"E — Typical engagement with social interaction, assertive action, activity, excitement and positive emotion.","definition":"Typical engagement with social interaction, assertive action, activity, excitement and positive emotion.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers quieter or more solitary settings.\nMay allow others to initiate interaction.\nCan favour a measured pace and lower stimulation.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often seeks social engagement and stimulation.\nIs more inclined to speak up or take the lead.\nCan prefer a busy and energetic pace.","anchor_low":"Often prefers quieter or more solitary settings.","anchor_high":"Often seeks social engagement and stimulation.","strength_commentary":"A quieter approach can suit independent concentration; an outgoing approach can suit frequent interaction. Effectiveness depends on the situation and behaviour.","development_suggestion":"Consider when to initiate and speak up, and when to listen, slow down or allow space for others.","display_order":1,"is_scored":true},{"id":"617f543c-d20b-5383-a19e-97a1e11d81a6","slug":"ipip-neo-120-johnson-2014-o-openness-to-experience","name":"Openness","description":"O — Interest in imagination, aesthetics, feelings, unfamiliar experiences, abstract ideas and reconsidering conventional values.","definition":"Interest in imagination, aesthetics, feelings, unfamiliar experiences, abstract ideas and reconsidering conventional values.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often favours familiar and concrete approaches.\nMay prefer established routines or views.\nCan place less emphasis on abstract or aesthetic exploration.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often explores ideas, imagination and unfamiliar experiences.\nMay attend closely to feelings or aesthetics.\nCan be more willing to question conventional views.","anchor_low":"Often favours familiar and concrete approaches.","anchor_high":"Often explores ideas, imagination and unfamiliar experiences.","strength_commentary":"Familiar approaches can support continuity; exploration can support discovering alternatives. This domain is not a test of intelligence, creativity performance or adaptability skill.","development_suggestion":"Choose where exploration could add value and where an established approach should be retained or tested carefully.","display_order":2,"is_scored":true},{"id":"37eaeec8-c545-5484-adeb-7c39141ecf85","slug":"ipip-neo-120-johnson-2014-a-agreeableness","name":"Agreeableness","description":"A — Typical interpersonal trust, candour, helpfulness, cooperation, modesty and concern for others.","definition":"Typical interpersonal trust, candour, helpfulness, cooperation, modesty and concern for others.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May be more sceptical or guarded with others.\nCan place personal interests or direct challenge first.\nMay take a more self-promoting or emotionally detached approach.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often gives others the benefit of the doubt.\nIs more inclined to help, cooperate and show concern.\nMay take a modest and accommodating approach.","anchor_low":"May be more sceptical or guarded with others.","anchor_high":"Often gives others the benefit of the doubt.","strength_commentary":"A challenging approach can surface disagreement; a cooperative approach can support relationships. Context determines whether trust, accommodation or challenge is appropriate.","development_suggestion":"Consider how to balance care and cooperation with clear boundaries, candid disagreement and appropriate scrutiny.","display_order":3,"is_scored":true},{"id":"96f9a279-2430-5bbd-a852-d150f2996afd","slug":"ipip-neo-120-johnson-2014-c-conscientiousness","name":"Conscientiousness","description":"C — Typical perceived effectiveness, orderliness, commitment, achievement striving, self-discipline and deliberation.","definition":"Typical perceived effectiveness, orderliness, commitment, achievement striving, self-discipline and deliberation.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May prefer a less structured or more spontaneous approach.\nCan be less focused on commitments, targets or sustained task effort.\nMay decide with less advance deliberation.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often organises work and takes commitments seriously.\nIs inclined to pursue goals and persist with tasks.\nMay think carefully before acting.","anchor_low":"May prefer a less structured or more spontaneous approach.","anchor_high":"Often organises work and takes commitments seriously.","strength_commentary":"Structure and persistence can support follow-through; a less structured style may allow spontaneity. Neither end establishes competence or actual delivery.","development_suggestion":"Review whether planning, effort and checking match the task, and where flexibility or a clearer commitment would help.","display_order":4,"is_scored":true}],"constructs":[{"id":"a194892c-2d9c-5ccf-a6f0-bf86d6fe86e5","slug":"ipip-neo-120-johnson-2014-n1-anxiety","name":"Anxiety","description":"N1 — Proneness to worry, fear and anticipatory tension.","definition":"Proneness to worry, fear and anticipatory tension.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Usually worries less.\nFeels less threatened by uncertain outcomes.\nReports fewer fears.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often anticipates what could go wrong.\nExperiences worry or tension readily.\nReports more fears.","anchor_low":"Usually worries less.","anchor_high":"Often anticipates what could go wrong.","strength_commentary":"Lower anxiety may make uncertainty easier to tolerate; greater concern can prompt preparation. Neither end establishes risk judgement.","development_suggestion":"Distinguish useful preparation from repetitive worry and identify a practical next action."},{"id":"19715e40-733c-5b82-a9a8-bde1eeb5b74d","slug":"ipip-neo-120-johnson-2014-n2-anger","name":"Irritability","description":"N2 — Readiness to experience irritation, frustration and anger.","definition":"Readiness to experience irritation, frustration and anger.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is usually difficult to irritate.\nReports less frequent anger.\nOften tolerates frustrations calmly.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Becomes irritated readily.\nMay experience anger when frustrated.\nCan react strongly to perceived provocation.","anchor_low":"Is usually difficult to irritate.","anchor_high":"Becomes irritated readily.","strength_commentary":"Lower anger can support calm exchanges; anger can signal that a boundary or concern needs attention. The expression and consequences of anger require separate evidence.","development_suggestion":"Notice early signs of irritation and choose how to express a concern without escalating the exchange."},{"id":"155e370a-1546-55b4-a616-393b597562a4","slug":"ipip-neo-120-johnson-2014-n3-depression","name":"Discouragement","description":"N3 — Tendency to experience low mood, discouragement and negative feelings about oneself, as represented by these personality items.","definition":"Tendency to experience low mood, discouragement and negative feelings about oneself, as represented by these personality items.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Reports fewer periods of feeling down.\nUsually feels more comfortable with oneself.\nIs less prone to discouragement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"More often feels down or discouraged.\nMay evaluate oneself negatively.\nReports less comfort with oneself.","anchor_low":"Reports fewer periods of feeling down.","anchor_high":"More often feels down or discouraged.","strength_commentary":"This is a personality facet score, not a diagnosis or a measure of clinical severity. Interpret experiences in context rather than labelling capability.","development_suggestion":"Reflect on situations associated with discouragement and the support, routines or adjustments that are helpful."},{"id":"ce398614-b3e2-57f1-a872-f7064a00cf42","slug":"ipip-neo-120-johnson-2014-n4-self-consciousness","name":"Social Confidence","description":"N4 — Reported comfort approaching others, receiving social attention and handling unfamiliar or difficult social situations.","definition":"Reported comfort approaching others, receiving social attention and handling unfamiliar or difficult social situations.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May hesitate to approach others.\nPrefers to avoid drawing attention.\nFeels less comfortable in unfamiliar social situations.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Is less troubled by social attention.\nApproaches unfamiliar people more readily.\nFeels less constrained by possible embarrassment.","anchor_low":"May hesitate to approach others.","anchor_high":"Is less troubled by social attention.","strength_commentary":"Lower discomfort can make public participation easier; greater sensitivity may encourage preparation. This facet does not measure self-awareness or insight.","development_suggestion":"Identify a manageable way to participate in situations where attention or unfamiliarity feels uncomfortable."},{"id":"de5e5ade-9bf9-5e5c-a260-795621cfc225","slug":"ipip-neo-120-johnson-2014-n5-immoderation","name":"Indulgence","description":"N5 — Difficulty resisting cravings, temptations and urges to overindulge.","definition":"Difficulty resisting cravings, temptations and urges to overindulge.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Finds temptations easier to resist.\nUsually regulates indulgence.\nReports more control over cravings.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Finds strong cravings harder to resist.\nMay overindulge.\nReports difficulty limiting tempting activities.","anchor_low":"Finds temptations easier to resist.","anchor_high":"Finds strong cravings harder to resist.","strength_commentary":"The content concerns regulation of appetites and indulgence. It should not be treated as a comprehensive measure of impulsive decision-making.","development_suggestion":"Identify tempting situations and decide in advance what limits or routines would be useful."},{"id":"43e29f79-221f-5a76-ae27-3b2da4c67e9d","slug":"ipip-neo-120-johnson-2014-n6-vulnerability","name":"Stress Tolerance","description":"N6 — Reported tendency to remain calm and feel able to cope under pressure rather than become overwhelmed.","definition":"Reported tendency to remain calm and feel able to cope under pressure rather than become overwhelmed.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Can become overwhelmed by events.\nMay panic under pressure.\nCan feel unable to deal with demands.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually feels able to cope under pressure.\nMaintains composure during difficult events.\nIs less readily overwhelmed.","anchor_low":"Can become overwhelmed by events.","anchor_high":"Usually feels able to cope under pressure.","strength_commentary":"Lower vulnerability reflects reported steadiness under stress; it does not demonstrate coping skill or recovery from adversity. Greater vulnerability can highlight situations that need support.","development_suggestion":"Identify demands that become overwhelming and the practical supports or actions that help restore control."},{"id":"fa2e986b-788c-5d9b-a591-8817ad53a853","slug":"ipip-neo-120-johnson-2014-e1-friendliness","name":"Friendliness","description":"E1 — Warmth and ease in approaching and engaging with other people.","definition":"Warmth and ease in approaching and engaging with other people.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Maintains more interpersonal distance.\nMay be slow to approach new people.\nCan prefer a more reserved manner.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Makes friends readily.\nFeels comfortable around people.\nOften engages with warmth.","anchor_low":"Maintains more interpersonal distance.","anchor_high":"Makes friends readily.","strength_commentary":"A reserved approach can preserve boundaries; warmth can make contact easier. Relationship effectiveness still depends on behaviour and context.","development_suggestion":"Choose when to initiate contact and when to respect personal or professional distance."},{"id":"b478a98a-65ed-55dd-a2a5-0cf242c075f6","slug":"ipip-neo-120-johnson-2014-e2-gregariousness","name":"Sociability","description":"E2 — Preference for company, crowds and frequent social interaction rather than solitude.","definition":"Preference for company, crowds and frequent social interaction rather than solitude.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers solitude or smaller settings.\nMay avoid crowds.\nNeeds less frequent social contact.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys being around many people.\nOften seeks group interaction.\nIs comfortable with crowded social settings.","anchor_low":"Often prefers solitude or smaller settings.","anchor_high":"Enjoys being around many people.","strength_commentary":"Solitude can support concentration and recovery; company can provide stimulation and connection. Neither preference establishes teamwork skill.","development_suggestion":"Plan a workable balance between social contact and quieter time."},{"id":"919a8d42-64c6-56e7-a693-978bb7720496","slug":"ipip-neo-120-johnson-2014-e3-assertiveness","name":"Assertiveness","description":"E3 — Inclination to take charge, express direction and assume a leading role.","definition":"Inclination to take charge, express direction and assume a leading role.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often lets others lead.\nMay be less inclined to take control.\nCan prefer a less directive role.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Readily takes charge.\nIs inclined to lead others.\nOften seeks control of group action.","anchor_low":"Often lets others lead.","anchor_high":"Readily takes charge.","strength_commentary":"Taking charge can help a group act; allowing others to lead can support participation. More assertiveness does not automatically produce more effective leadership.","development_suggestion":"Consider when clear direction is needed and when to invite input or share control."},{"id":"2185a01b-2027-5839-a4a5-2e57978ffb49","slug":"ipip-neo-120-johnson-2014-e4-activity-level","name":"Activity Level","description":"E4 — Preference for a busy, active and fast-moving pace of life.","definition":"Preference for a busy, active and fast-moving pace of life.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers a leisurely pace.\nAllows more downtime.\nMay avoid keeping continuously busy.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often stays busy.\nPrefers frequent activity.\nMay maintain a demanding pace.","anchor_low":"Often prefers a leisurely pace.","anchor_high":"Often stays busy.","strength_commentary":"A measured pace can allow reflection and recovery; activity can support engagement with a busy environment. This facet does not establish productivity.","development_suggestion":"Check whether your pace matches the task and whether adequate recovery or momentum is needed."},{"id":"541a1b2f-9dbc-5969-ab99-6649a16d8651","slug":"ipip-neo-120-johnson-2014-e5-excitement-seeking","name":"Excitement-Seeking","description":"E5 — Appetite for excitement, adventure and stimulating or potentially reckless experiences.","definition":"Appetite for excitement, adventure and stimulating or potentially reckless experiences.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Prefers lower stimulation.\nMay avoid adventurous situations.\nUsually has less appetite for excitement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Seeks excitement and adventure.\nEnjoys strong stimulation.\nMay be attracted to reckless experiences.","anchor_low":"Prefers lower stimulation.","anchor_high":"Seeks excitement and adventure.","strength_commentary":"Lower stimulation can suit predictable settings; excitement can make stimulating settings appealing. This facet does not establish the quality of risk decisions.","development_suggestion":"Distinguish the appeal of excitement from the benefits and consequences of a particular action."},{"id":"79ad7769-6c4b-5ef3-a988-5bb9187478aa","slug":"ipip-neo-120-johnson-2014-e6-cheerfulness","name":"Cheerfulness","description":"E6 — Frequency and expression of positive emotion, enjoyment and enthusiasm.","definition":"Frequency and expression of positive emotion, enjoyment and enthusiasm.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Expresses less visible joy.\nMay experience positive emotion less frequently.\nCan take a more subdued emotional tone.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often feels and expresses joy.\nReadily finds enjoyment.\nCan take an enthusiastic or positive tone.","anchor_low":"Expresses less visible joy.","anchor_high":"Often feels and expresses joy.","strength_commentary":"A subdued style need not indicate distress; cheerfulness can make positive engagement visible. Neither end alone establishes realism or performance.","development_suggestion":"Consider how your emotional expression affects others and when a realistic concern should also be voiced."},{"id":"d51544ae-849f-5da3-af5b-ad3085451dd7","slug":"ipip-neo-120-johnson-2014-o1-imagination","name":"Imagination","description":"O1 — Interest in fantasy, daydreaming and a vivid inner imaginative life.","definition":"Interest in fantasy, daydreaming and a vivid inner imaginative life.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Focuses more on concrete experience.\nSpends less time daydreaming.\nMay have less interest in fantasy.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys vivid imagination.\nOften daydreams.\nCan become absorbed in fantasy or thought.","anchor_low":"Focuses more on concrete experience.","anchor_high":"Enjoys vivid imagination.","strength_commentary":"Concrete attention can support practical focus; imagination can provide possibilities. This facet is not a test of creative problem-solving performance.","development_suggestion":"Choose when imaginative exploration is useful and how to connect possibilities with practical action."},{"id":"1bef2781-aa31-5e2e-acea-0336017f37bf","slug":"ipip-neo-120-johnson-2014-o2-artistic-interests","name":"Artistic Interests","description":"O2 — Interest in art, poetry, beauty and aesthetic experience.","definition":"Interest in art, poetry, beauty and aesthetic experience.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Has less interest in artistic activities.\nMay give aesthetics less attention.\nOften prefers other forms of engagement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Values artistic experience.\nNotices beauty.\nMay enjoy art, poetry or museums.","anchor_low":"Has less interest in artistic activities.","anchor_high":"Values artistic experience.","strength_commentary":"Different levels of artistic interest reflect preferences rather than artistic skill or leadership capability.","development_suggestion":"Consider whether aesthetic experiences add enjoyment or perspective without treating them as a performance requirement."},{"id":"8eb56c2d-9e44-569c-af0b-aa4570d05adb","slug":"ipip-neo-120-johnson-2014-o3-emotionality","name":"Emotional Sensitivity","description":"O3 — Attention to, intensity of and interest in emotional experience.","definition":"Attention to, intensity of and interest in emotional experience.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Pays less attention to emotional reactions.\nMay experience feelings less intensely.\nCan find emotional expression harder to relate to.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Experiences feelings intensely.\nNotices emotional responses.\nOften attends to others'' emotions.","anchor_low":"Pays less attention to emotional reactions.","anchor_high":"Experiences feelings intensely.","strength_commentary":"Lower emotional emphasis can support emotional distance; stronger emotional experience can bring feelings into awareness. This facet does not establish emotion-reading accuracy or emotional intelligence.","development_suggestion":"Notice relevant feelings while checking interpretations of other people''s emotions through conversation."},{"id":"d0bf1cc9-61c1-5a65-a51c-2bb09a570d55","slug":"ipip-neo-120-johnson-2014-o4-adventurousness","name":"Variety Seeking","description":"O4 — Preference for variety and unfamiliar experiences rather than familiar routines and conventional ways.","definition":"Preference for variety and unfamiliar experiences rather than familiar routines and conventional ways.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often favours familiar approaches.\nPrefers established routines.\nMay dislike changes to known ways.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys variety.\nIs more open to unfamiliar experiences.\nMay be less attached to conventional routines.","anchor_low":"Often favours familiar approaches.","anchor_high":"Enjoys variety.","strength_commentary":"Familiarity can support continuity; variety can support exploration. Preference for change is different from effective adaptation to change.","development_suggestion":"Decide where trying something unfamiliar is worthwhile and what preparation or continuity is needed."},{"id":"4dbaa128-aef1-516f-aed7-d242ea729522","slug":"ipip-neo-120-johnson-2014-o5-intellect","name":"Intellectual Curiosity","description":"O5 — Interest in abstract ideas, challenging material and theoretical or philosophical discussion.","definition":"Interest in abstract ideas, challenging material and theoretical or philosophical discussion.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers concrete or practical material.\nHas less interest in theoretical discussion.\nMay find abstract ideas less appealing.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys challenging reading.\nIs interested in abstract ideas.\nOften engages with theory or philosophy.","anchor_low":"Often prefers concrete or practical material.","anchor_high":"Enjoys challenging reading.","strength_commentary":"Concrete and abstract interests can each suit different work. This is a self-report personality facet, not an intelligence or reasoning test.","development_suggestion":"Match the level of abstraction to the problem and seek evidence that ideas can explain or improve something useful."},{"id":"2a7d6ae7-7015-51f4-a4a9-4eece9162d67","slug":"ipip-neo-120-johnson-2014-o6-liberalism","name":"Liberalism","description":"O6 — Willingness to question conventional social values, as operationalised here using political and moral-attitude items.","definition":"Willingness to question conventional social values, as operationalised here using political and moral-attitude items.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"More often endorses conventional or conservative views.\nMay favour established social rules.\nCan prefer firmer moral boundaries.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"More often endorses liberal political views.\nMay question absolute moral rules.\nCan be more willing to reconsider conventions.","anchor_low":"More often endorses conventional or conservative views.","anchor_high":"More often endorses liberal political views.","strength_commentary":"The original English items concern political and moral attitudes. This facet does not establish leadership quality, fairness, learning agility or organisational suitability.","development_suggestion":"Discuss the meaning of differing views without treating a political preference as a capability score."},{"id":"69b85b5b-4c5b-54dc-a5bc-af17d7f6f32f","slug":"ipip-neo-120-johnson-2014-a1-trust","name":"Trust","description":"A1 — Readiness to believe that other people are honest, well-intentioned and dependable.","definition":"Readiness to believe that other people are honest, well-intentioned and dependable.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is more sceptical of others'' intentions.\nMay verify claims before relying on them.\nCan be guarded in extending trust.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Gives others the benefit of the doubt.\nOften assumes good intentions.\nReadily believes what others say.","anchor_low":"Is more sceptical of others'' intentions.","anchor_high":"Gives others the benefit of the doubt.","strength_commentary":"Scrutiny can protect against misplaced trust; trust can make cooperation easier. The appropriate balance depends on evidence and consequences.","development_suggestion":"Choose how much trust to extend and what verification is proportionate to the situation."},{"id":"3a097cb2-8d4d-5849-a912-d3f8e2bdfcaa","slug":"ipip-neo-120-johnson-2014-a2-morality","name":"Fairness","description":"A2 — Reported avoidance of cheating, manipulating, exploiting or obstructing other people. This does not establish impartiality, justice or verified ethical conduct.","definition":"Reported avoidance of cheating, manipulating, exploiting or obstructing other people. This does not establish impartiality, justice or verified ethical conduct.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May endorse more instrumental treatment of others.\nCan be more willing to gain advantage at others'' expense.\nMay report obstructive or exploitative behaviour.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Reports avoiding exploitation or cheating.\nIs less inclined to manipulate others for gain.\nUsually rejects obstructing others for personal advantage.","anchor_low":"May endorse more instrumental treatment of others.","anchor_high":"Reports avoiding exploitation or cheating.","strength_commentary":"The retained scale label is Morality. These self-reports are not verification of integrity, ethical conduct or honesty-humility.","development_suggestion":"Examine concrete decisions and their effects on other people rather than treating the label as a character verdict."},{"id":"62478abb-b66e-565a-a065-83d5f09bddb6","slug":"ipip-neo-120-johnson-2014-a3-altruism","name":"Helpfulness","description":"A3 — Inclination to care about other people''s needs and offer practical help.","definition":"Inclination to care about other people''s needs and offer practical help.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May give others'' needs less attention.\nIs less inclined to spend time helping.\nCan prefer clearer boundaries around assistance.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often offers help.\nShows concern for others.\nIs willing to spend time supporting people.","anchor_low":"May give others'' needs less attention.","anchor_high":"Often offers help.","strength_commentary":"Boundaries can protect capacity; helping can support others. Effective support requires attention to what help is needed and what is sustainable.","development_suggestion":"Balance useful assistance with clear priorities, consent and sustainable boundaries."},{"id":"104e3fe5-2546-55d5-a532-73a7ab4ecc0f","slug":"ipip-neo-120-johnson-2014-a4-cooperation","name":"Cooperation","description":"A4 — Inclination to avoid interpersonal aggression, retaliation and unnecessary conflict.","definition":"Inclination to avoid interpersonal aggression, retaliation and unnecessary conflict.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May be more confrontational.\nCan respond to conflict with hostility.\nMay be inclined to retaliate.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Is less inclined to insult or retaliate.\nOften avoids aggressive exchanges.\nCan prefer an accommodating approach.","anchor_low":"May be more confrontational.","anchor_high":"Is less inclined to insult or retaliate.","strength_commentary":"A cooperative approach can reduce friction. Constructive disagreement and assertive boundaries should be distinguished from the aggression represented by the lower end.","development_suggestion":"Raise disagreements directly while avoiding insults, revenge or unnecessary escalation."},{"id":"a83108fc-d731-5adc-aba4-a30fdc7f8dc3","slug":"ipip-neo-120-johnson-2014-a5-modesty","name":"Modesty","description":"A5 — Restraint in claiming superiority, praising oneself or drawing attention to one''s virtues.","definition":"Restraint in claiming superiority, praising oneself or drawing attention to one''s virtues.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Readily expresses a high opinion of oneself.\nMay emphasise personal virtues.\nCan make superiority claims.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Avoids claiming superiority.\nIs less inclined to boast.\nMay downplay personal virtues.","anchor_low":"Readily expresses a high opinion of oneself.","anchor_high":"Avoids claiming superiority.","strength_commentary":"Visible self-advocacy can communicate achievements; modesty can leave room for others. This facet does not establish accurate self-insight or confidence.","development_suggestion":"Describe achievements with evidence while recognising the contributions and strengths of others."},{"id":"b6b2f051-dbff-5a89-a25b-e1638f10558e","slug":"ipip-neo-120-johnson-2014-a6-sympathy","name":"Compassion","description":"A6 — Compassion and concern for people experiencing hardship or disadvantage.","definition":"Compassion and concern for people experiencing hardship or disadvantage.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Maintains more distance from others'' difficulties.\nMay give hardship less attention.\nCan prefer to avoid distressing concerns.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Feels concern for people facing hardship.\nResponds with compassion.\nOften attends to others'' difficulties.","anchor_low":"Maintains more distance from others'' difficulties.","anchor_high":"Feels concern for people facing hardship.","strength_commentary":"Emotional distance can help maintain boundaries; compassion can draw attention to unmet needs. Neither alone establishes sound decisions or effective assistance.","development_suggestion":"Consider others'' needs alongside evidence, fairness and the practical consequences of a response."},{"id":"2c56d6f2-dc03-5777-a1b1-10158db82d40","slug":"ipip-neo-120-johnson-2014-c1-self-efficacy","name":"Perceived Competence","description":"C1 — Belief in one''s effectiveness at completing tasks and handling practical demands. This is perceived competence, not independently demonstrated ability.","definition":"Belief in one''s effectiveness at completing tasks and handling practical demands. This is perceived competence, not independently demonstrated ability.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Reports less confidence in task effectiveness.\nMay doubt how well tasks will be handled.\nCan feel less certain about getting things done.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Reports confidence in completing tasks.\nFeels able to handle demands.\nUsually expects to know how to get things done.","anchor_low":"Reports less confidence in task effectiveness.","anchor_high":"Reports confidence in completing tasks.","strength_commentary":"Confidence can support willingness to act; doubt can encourage checking or assistance. This facet measures perceived effectiveness rather than demonstrated competence.","development_suggestion":"Compare confidence with task evidence and identify where practice, feedback or help would improve calibration."},{"id":"a834ac0f-5778-5cf7-a6ca-b8a7ace6ce62","slug":"ipip-neo-120-johnson-2014-c2-orderliness","name":"Orderliness","description":"C2 — Preference for tidiness, organisation and returning belongings to their proper place.","definition":"Preference for tidiness, organisation and returning belongings to their proper place.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is less concerned with tidiness.\nMay leave belongings out of place.\nCan prefer a less orderly environment.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually keeps things tidy.\nReturns belongings to their place.\nPrefers an orderly environment.","anchor_low":"Is less concerned with tidiness.","anchor_high":"Usually keeps things tidy.","strength_commentary":"An orderly environment can make retrieval and routines easier; less concern with tidiness may suit some flexible settings. This facet does not establish planning or management skill.","development_suggestion":"Use enough structure to make work manageable without adding organisation that serves little purpose."},{"id":"a21bc961-b199-503a-a8d8-ecb0e216ed8d","slug":"ipip-neo-120-johnson-2014-c3-dutifulness","name":"Dependability","description":"C3 — Reported commitment to promises, truthfulness and following rules.","definition":"Reported commitment to promises, truthfulness and following rules.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May treat commitments or rules more flexibly.\nCan report breaking promises.\nMay be less consistent about truthfulness.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually reports keeping promises.\nTakes rules and commitments seriously.\nEndorses telling the truth.","anchor_low":"May treat commitments or rules more flexibly.","anchor_high":"Usually reports keeping promises.","strength_commentary":"Commitment can support reliability. Whether a rule should be followed or challenged requires judgement beyond this self-report facet.","development_suggestion":"Make commitments explicitly, raise difficulties early and explain any necessary challenge to an inappropriate rule."},{"id":"a3011e81-edce-52af-aea2-6a47639a6db4","slug":"ipip-neo-120-johnson-2014-c4-achievement-striving","name":"Achievement Striving","description":"C4 — Willingness to work hard, exceed requirements and invest effort in achievement.","definition":"Willingness to work hard, exceed requirements and invest effort in achievement.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May be satisfied with meeting minimum requirements.\nOften invests less additional effort.\nCan place less emphasis on demanding achievement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often works hard.\nTries to exceed expectations.\nInvests effort in achieving more.","anchor_low":"May be satisfied with meeting minimum requirements.","anchor_high":"Often works hard.","strength_commentary":"A measured level of striving can protect other priorities; strong striving can sustain demanding goals. Actual outcomes and the value of the goals require separate evidence.","development_suggestion":"Choose goals deliberately and check that effort remains proportionate to priorities and available capacity."},{"id":"e9fb96e7-af17-5a37-ae15-072e5a68b9a6","slug":"ipip-neo-120-johnson-2014-c5-self-discipline","name":"Self-Discipline","description":"C5 — Inclination to start tasks, stay prepared and carry plans through rather than delay or waste time.","definition":"Inclination to start tasks, stay prepared and carry plans through rather than delay or waste time.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May delay starting tasks.\nCan find follow-through difficult.\nMay spend time on competing distractions.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often starts tasks readily.\nPrepares for what needs doing.\nUsually carries out plans.","anchor_low":"May delay starting tasks.","anchor_high":"Often starts tasks readily.","strength_commentary":"Sustained task focus can support completion; willingness to pause can sometimes allow reprioritisation. The facet does not establish whether a task should be continued.","development_suggestion":"Identify the next useful action and review whether persistence or a deliberate change of plan is needed."},{"id":"3fabe2e0-e251-5c09-a4f5-115853060a63","slug":"ipip-neo-120-johnson-2014-c6-cautiousness","name":"Deliberation","description":"C6 — Tendency to deliberate before acting rather than rush into decisions.","definition":"Tendency to deliberate before acting rather than rush into decisions.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May act quickly with limited advance thought.\nCan make spontaneous decisions.\nMay rush into action.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually thinks before acting.\nIs less inclined to make rash decisions.\nOften considers actions in advance.","anchor_low":"May act quickly with limited advance thought.","anchor_high":"Usually thinks before acting.","strength_commentary":"Speed can matter when action is urgent; deliberation can help examine consequences. Neither end establishes decision quality or an appropriate appetite for risk.","development_suggestion":"Match the amount of deliberation to the stakes, time available and reversibility of the decision."}],"factors":[{"id":"fd95d192-570f-5449-aa8d-cc32ff5ac13a","slug":"ipip-neo-120-johnson-2014-n1-anxiety","name":"Anxiety","description":"N1 — Proneness to worry, fear and anticipatory tension.","definition":"Proneness to worry, fear and anticipatory tension.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Usually worries less.\nFeels less threatened by uncertain outcomes.\nReports fewer fears.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often anticipates what could go wrong.\nExperiences worry or tension readily.\nReports more fears.","anchor_low":"Usually worries less.","anchor_high":"Often anticipates what could go wrong.","strength_commentary":"Lower anxiety may make uncertainty easier to tolerate; greater concern can prompt preparation. Neither end establishes risk judgement.","development_suggestion":"Distinguish useful preparation from repetitive worry and identify a practical next action.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"719b6184-0aab-5120-a543-6ea246c75614","slug":"ipip-neo-120-johnson-2014-n2-anger","name":"Irritability","description":"N2 — Readiness to experience irritation, frustration and anger.","definition":"Readiness to experience irritation, frustration and anger.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is usually difficult to irritate.\nReports less frequent anger.\nOften tolerates frustrations calmly.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Becomes irritated readily.\nMay experience anger when frustrated.\nCan react strongly to perceived provocation.","anchor_low":"Is usually difficult to irritate.","anchor_high":"Becomes irritated readily.","strength_commentary":"Lower anger can support calm exchanges; anger can signal that a boundary or concern needs attention. The expression and consequences of anger require separate evidence.","development_suggestion":"Notice early signs of irritation and choose how to express a concern without escalating the exchange.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"e7d10d8a-8010-5600-ac49-10d8a8e98b40","slug":"ipip-neo-120-johnson-2014-n3-depression","name":"Discouragement","description":"N3 — Tendency to experience low mood, discouragement and negative feelings about oneself, as represented by these personality items.","definition":"Tendency to experience low mood, discouragement and negative feelings about oneself, as represented by these personality items.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Reports fewer periods of feeling down.\nUsually feels more comfortable with oneself.\nIs less prone to discouragement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"More often feels down or discouraged.\nMay evaluate oneself negatively.\nReports less comfort with oneself.","anchor_low":"Reports fewer periods of feeling down.","anchor_high":"More often feels down or discouraged.","strength_commentary":"This is a personality facet score, not a diagnosis or a measure of clinical severity. Interpret experiences in context rather than labelling capability.","development_suggestion":"Reflect on situations associated with discouragement and the support, routines or adjustments that are helpful.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"79406023-774e-57c5-a9e8-2b7ff83073d4","slug":"ipip-neo-120-johnson-2014-n4-self-consciousness","name":"Social Confidence","description":"N4 — Reported comfort approaching others, receiving social attention and handling unfamiliar or difficult social situations.","definition":"Reported comfort approaching others, receiving social attention and handling unfamiliar or difficult social situations.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May hesitate to approach others.\nPrefers to avoid drawing attention.\nFeels less comfortable in unfamiliar social situations.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Is less troubled by social attention.\nApproaches unfamiliar people more readily.\nFeels less constrained by possible embarrassment.","anchor_low":"May hesitate to approach others.","anchor_high":"Is less troubled by social attention.","strength_commentary":"Lower discomfort can make public participation easier; greater sensitivity may encourage preparation. This facet does not measure self-awareness or insight.","development_suggestion":"Identify a manageable way to participate in situations where attention or unfamiliarity feels uncomfortable.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"837da813-c25c-5684-a99c-722c4f4e43a5","slug":"ipip-neo-120-johnson-2014-n5-immoderation","name":"Indulgence","description":"N5 — Difficulty resisting cravings, temptations and urges to overindulge.","definition":"Difficulty resisting cravings, temptations and urges to overindulge.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Finds temptations easier to resist.\nUsually regulates indulgence.\nReports more control over cravings.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Finds strong cravings harder to resist.\nMay overindulge.\nReports difficulty limiting tempting activities.","anchor_low":"Finds temptations easier to resist.","anchor_high":"Finds strong cravings harder to resist.","strength_commentary":"The content concerns regulation of appetites and indulgence. It should not be treated as a comprehensive measure of impulsive decision-making.","development_suggestion":"Identify tempting situations and decide in advance what limits or routines would be useful.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"01b3745a-9d63-58d8-ac8a-e2b1b0ca224d","slug":"ipip-neo-120-johnson-2014-n6-vulnerability","name":"Stress Tolerance","description":"N6 — Reported tendency to remain calm and feel able to cope under pressure rather than become overwhelmed.","definition":"Reported tendency to remain calm and feel able to cope under pressure rather than become overwhelmed.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Can become overwhelmed by events.\nMay panic under pressure.\nCan feel unable to deal with demands.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually feels able to cope under pressure.\nMaintains composure during difficult events.\nIs less readily overwhelmed.","anchor_low":"Can become overwhelmed by events.","anchor_high":"Usually feels able to cope under pressure.","strength_commentary":"Lower vulnerability reflects reported steadiness under stress; it does not demonstrate coping skill or recovery from adversity. Greater vulnerability can highlight situations that need support.","development_suggestion":"Identify demands that become overwhelming and the practical supports or actions that help restore control.","dimension_id":"8cd76c06-e099-51f7-a0fb-7848357a3417","composition_locked":true,"is_match_eligible":false},{"id":"d61dde63-45eb-53c2-a896-4e232236ffc9","slug":"ipip-neo-120-johnson-2014-e1-friendliness","name":"Friendliness","description":"E1 — Warmth and ease in approaching and engaging with other people.","definition":"Warmth and ease in approaching and engaging with other people.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Maintains more interpersonal distance.\nMay be slow to approach new people.\nCan prefer a more reserved manner.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Makes friends readily.\nFeels comfortable around people.\nOften engages with warmth.","anchor_low":"Maintains more interpersonal distance.","anchor_high":"Makes friends readily.","strength_commentary":"A reserved approach can preserve boundaries; warmth can make contact easier. Relationship effectiveness still depends on behaviour and context.","development_suggestion":"Choose when to initiate contact and when to respect personal or professional distance.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"fcddb27a-cc2a-50c4-acb0-afb324b0808f","slug":"ipip-neo-120-johnson-2014-e2-gregariousness","name":"Sociability","description":"E2 — Preference for company, crowds and frequent social interaction rather than solitude.","definition":"Preference for company, crowds and frequent social interaction rather than solitude.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers solitude or smaller settings.\nMay avoid crowds.\nNeeds less frequent social contact.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys being around many people.\nOften seeks group interaction.\nIs comfortable with crowded social settings.","anchor_low":"Often prefers solitude or smaller settings.","anchor_high":"Enjoys being around many people.","strength_commentary":"Solitude can support concentration and recovery; company can provide stimulation and connection. Neither preference establishes teamwork skill.","development_suggestion":"Plan a workable balance between social contact and quieter time.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"e1253ba5-6c81-5224-a141-27dd8be4fe78","slug":"ipip-neo-120-johnson-2014-e3-assertiveness","name":"Assertiveness","description":"E3 — Inclination to take charge, express direction and assume a leading role.","definition":"Inclination to take charge, express direction and assume a leading role.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often lets others lead.\nMay be less inclined to take control.\nCan prefer a less directive role.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Readily takes charge.\nIs inclined to lead others.\nOften seeks control of group action.","anchor_low":"Often lets others lead.","anchor_high":"Readily takes charge.","strength_commentary":"Taking charge can help a group act; allowing others to lead can support participation. More assertiveness does not automatically produce more effective leadership.","development_suggestion":"Consider when clear direction is needed and when to invite input or share control.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"d28363f8-db45-5246-a725-c700c2afdebe","slug":"ipip-neo-120-johnson-2014-e4-activity-level","name":"Activity Level","description":"E4 — Preference for a busy, active and fast-moving pace of life.","definition":"Preference for a busy, active and fast-moving pace of life.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers a leisurely pace.\nAllows more downtime.\nMay avoid keeping continuously busy.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often stays busy.\nPrefers frequent activity.\nMay maintain a demanding pace.","anchor_low":"Often prefers a leisurely pace.","anchor_high":"Often stays busy.","strength_commentary":"A measured pace can allow reflection and recovery; activity can support engagement with a busy environment. This facet does not establish productivity.","development_suggestion":"Check whether your pace matches the task and whether adequate recovery or momentum is needed.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"2ee6dca2-c97e-55e2-a55d-6999e2597b15","slug":"ipip-neo-120-johnson-2014-e5-excitement-seeking","name":"Excitement-Seeking","description":"E5 — Appetite for excitement, adventure and stimulating or potentially reckless experiences.","definition":"Appetite for excitement, adventure and stimulating or potentially reckless experiences.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Prefers lower stimulation.\nMay avoid adventurous situations.\nUsually has less appetite for excitement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Seeks excitement and adventure.\nEnjoys strong stimulation.\nMay be attracted to reckless experiences.","anchor_low":"Prefers lower stimulation.","anchor_high":"Seeks excitement and adventure.","strength_commentary":"Lower stimulation can suit predictable settings; excitement can make stimulating settings appealing. This facet does not establish the quality of risk decisions.","development_suggestion":"Distinguish the appeal of excitement from the benefits and consequences of a particular action.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"c11a6b05-63f6-50b6-a68d-06af9b5c66e3","slug":"ipip-neo-120-johnson-2014-e6-cheerfulness","name":"Cheerfulness","description":"E6 — Frequency and expression of positive emotion, enjoyment and enthusiasm.","definition":"Frequency and expression of positive emotion, enjoyment and enthusiasm.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Expresses less visible joy.\nMay experience positive emotion less frequently.\nCan take a more subdued emotional tone.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often feels and expresses joy.\nReadily finds enjoyment.\nCan take an enthusiastic or positive tone.","anchor_low":"Expresses less visible joy.","anchor_high":"Often feels and expresses joy.","strength_commentary":"A subdued style need not indicate distress; cheerfulness can make positive engagement visible. Neither end alone establishes realism or performance.","development_suggestion":"Consider how your emotional expression affects others and when a realistic concern should also be voiced.","dimension_id":"f3531906-ff75-5f40-a7eb-65634f819ac1","composition_locked":true,"is_match_eligible":false},{"id":"d38a4b24-6215-58ae-a036-36ffe82f41e4","slug":"ipip-neo-120-johnson-2014-o1-imagination","name":"Imagination","description":"O1 — Interest in fantasy, daydreaming and a vivid inner imaginative life.","definition":"Interest in fantasy, daydreaming and a vivid inner imaginative life.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Focuses more on concrete experience.\nSpends less time daydreaming.\nMay have less interest in fantasy.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys vivid imagination.\nOften daydreams.\nCan become absorbed in fantasy or thought.","anchor_low":"Focuses more on concrete experience.","anchor_high":"Enjoys vivid imagination.","strength_commentary":"Concrete attention can support practical focus; imagination can provide possibilities. This facet is not a test of creative problem-solving performance.","development_suggestion":"Choose when imaginative exploration is useful and how to connect possibilities with practical action.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"5ff3bde1-aae2-54e9-ae65-48584f1abcfd","slug":"ipip-neo-120-johnson-2014-o2-artistic-interests","name":"Artistic Interests","description":"O2 — Interest in art, poetry, beauty and aesthetic experience.","definition":"Interest in art, poetry, beauty and aesthetic experience.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Has less interest in artistic activities.\nMay give aesthetics less attention.\nOften prefers other forms of engagement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Values artistic experience.\nNotices beauty.\nMay enjoy art, poetry or museums.","anchor_low":"Has less interest in artistic activities.","anchor_high":"Values artistic experience.","strength_commentary":"Different levels of artistic interest reflect preferences rather than artistic skill or leadership capability.","development_suggestion":"Consider whether aesthetic experiences add enjoyment or perspective without treating them as a performance requirement.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"c8520758-ce50-5e44-ab40-2a39e69b82bf","slug":"ipip-neo-120-johnson-2014-o3-emotionality","name":"Emotional Sensitivity","description":"O3 — Attention to, intensity of and interest in emotional experience.","definition":"Attention to, intensity of and interest in emotional experience.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Pays less attention to emotional reactions.\nMay experience feelings less intensely.\nCan find emotional expression harder to relate to.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Experiences feelings intensely.\nNotices emotional responses.\nOften attends to others'' emotions.","anchor_low":"Pays less attention to emotional reactions.","anchor_high":"Experiences feelings intensely.","strength_commentary":"Lower emotional emphasis can support emotional distance; stronger emotional experience can bring feelings into awareness. This facet does not establish emotion-reading accuracy or emotional intelligence.","development_suggestion":"Notice relevant feelings while checking interpretations of other people''s emotions through conversation.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"e5c67d99-f48e-54cd-a14c-48188046413d","slug":"ipip-neo-120-johnson-2014-o4-adventurousness","name":"Variety Seeking","description":"O4 — Preference for variety and unfamiliar experiences rather than familiar routines and conventional ways.","definition":"Preference for variety and unfamiliar experiences rather than familiar routines and conventional ways.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often favours familiar approaches.\nPrefers established routines.\nMay dislike changes to known ways.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys variety.\nIs more open to unfamiliar experiences.\nMay be less attached to conventional routines.","anchor_low":"Often favours familiar approaches.","anchor_high":"Enjoys variety.","strength_commentary":"Familiarity can support continuity; variety can support exploration. Preference for change is different from effective adaptation to change.","development_suggestion":"Decide where trying something unfamiliar is worthwhile and what preparation or continuity is needed.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"1950ddd2-2ff3-5c91-a444-e91caa56b816","slug":"ipip-neo-120-johnson-2014-o5-intellect","name":"Intellectual Curiosity","description":"O5 — Interest in abstract ideas, challenging material and theoretical or philosophical discussion.","definition":"Interest in abstract ideas, challenging material and theoretical or philosophical discussion.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Often prefers concrete or practical material.\nHas less interest in theoretical discussion.\nMay find abstract ideas less appealing.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Enjoys challenging reading.\nIs interested in abstract ideas.\nOften engages with theory or philosophy.","anchor_low":"Often prefers concrete or practical material.","anchor_high":"Enjoys challenging reading.","strength_commentary":"Concrete and abstract interests can each suit different work. This is a self-report personality facet, not an intelligence or reasoning test.","development_suggestion":"Match the level of abstraction to the problem and seek evidence that ideas can explain or improve something useful.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"62436447-61ae-55df-a235-22cb899cc59b","slug":"ipip-neo-120-johnson-2014-o6-liberalism","name":"Liberalism","description":"O6 — Willingness to question conventional social values, as operationalised here using political and moral-attitude items.","definition":"Willingness to question conventional social values, as operationalised here using political and moral-attitude items.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"More often endorses conventional or conservative views.\nMay favour established social rules.\nCan prefer firmer moral boundaries.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"More often endorses liberal political views.\nMay question absolute moral rules.\nCan be more willing to reconsider conventions.","anchor_low":"More often endorses conventional or conservative views.","anchor_high":"More often endorses liberal political views.","strength_commentary":"The original English items concern political and moral attitudes. This facet does not establish leadership quality, fairness, learning agility or organisational suitability.","development_suggestion":"Discuss the meaning of differing views without treating a political preference as a capability score.","dimension_id":"617f543c-d20b-5383-a19e-97a1e11d81a6","composition_locked":true,"is_match_eligible":false},{"id":"bcefce68-5824-57a2-acf7-f1bd300a14d2","slug":"ipip-neo-120-johnson-2014-a1-trust","name":"Trust","description":"A1 — Readiness to believe that other people are honest, well-intentioned and dependable.","definition":"Readiness to believe that other people are honest, well-intentioned and dependable.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is more sceptical of others'' intentions.\nMay verify claims before relying on them.\nCan be guarded in extending trust.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Gives others the benefit of the doubt.\nOften assumes good intentions.\nReadily believes what others say.","anchor_low":"Is more sceptical of others'' intentions.","anchor_high":"Gives others the benefit of the doubt.","strength_commentary":"Scrutiny can protect against misplaced trust; trust can make cooperation easier. The appropriate balance depends on evidence and consequences.","development_suggestion":"Choose how much trust to extend and what verification is proportionate to the situation.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"2c20d492-a0dc-5742-a1d5-4283e3ddd34f","slug":"ipip-neo-120-johnson-2014-a2-morality","name":"Fairness","description":"A2 — Reported avoidance of cheating, manipulating, exploiting or obstructing other people. This does not establish impartiality, justice or verified ethical conduct.","definition":"Reported avoidance of cheating, manipulating, exploiting or obstructing other people. This does not establish impartiality, justice or verified ethical conduct.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May endorse more instrumental treatment of others.\nCan be more willing to gain advantage at others'' expense.\nMay report obstructive or exploitative behaviour.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Reports avoiding exploitation or cheating.\nIs less inclined to manipulate others for gain.\nUsually rejects obstructing others for personal advantage.","anchor_low":"May endorse more instrumental treatment of others.","anchor_high":"Reports avoiding exploitation or cheating.","strength_commentary":"The retained scale label is Morality. These self-reports are not verification of integrity, ethical conduct or honesty-humility.","development_suggestion":"Examine concrete decisions and their effects on other people rather than treating the label as a character verdict.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"e474a4f8-2a4d-55c3-aa8a-0bc1f32633a9","slug":"ipip-neo-120-johnson-2014-a3-altruism","name":"Helpfulness","description":"A3 — Inclination to care about other people''s needs and offer practical help.","definition":"Inclination to care about other people''s needs and offer practical help.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May give others'' needs less attention.\nIs less inclined to spend time helping.\nCan prefer clearer boundaries around assistance.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often offers help.\nShows concern for others.\nIs willing to spend time supporting people.","anchor_low":"May give others'' needs less attention.","anchor_high":"Often offers help.","strength_commentary":"Boundaries can protect capacity; helping can support others. Effective support requires attention to what help is needed and what is sustainable.","development_suggestion":"Balance useful assistance with clear priorities, consent and sustainable boundaries.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"bb47248f-a8b9-5af4-a13a-408491505948","slug":"ipip-neo-120-johnson-2014-a4-cooperation","name":"Cooperation","description":"A4 — Inclination to avoid interpersonal aggression, retaliation and unnecessary conflict.","definition":"Inclination to avoid interpersonal aggression, retaliation and unnecessary conflict.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May be more confrontational.\nCan respond to conflict with hostility.\nMay be inclined to retaliate.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Is less inclined to insult or retaliate.\nOften avoids aggressive exchanges.\nCan prefer an accommodating approach.","anchor_low":"May be more confrontational.","anchor_high":"Is less inclined to insult or retaliate.","strength_commentary":"A cooperative approach can reduce friction. Constructive disagreement and assertive boundaries should be distinguished from the aggression represented by the lower end.","development_suggestion":"Raise disagreements directly while avoiding insults, revenge or unnecessary escalation.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"983a31c6-925c-5ca9-ad8c-86208dbd3327","slug":"ipip-neo-120-johnson-2014-a5-modesty","name":"Modesty","description":"A5 — Restraint in claiming superiority, praising oneself or drawing attention to one''s virtues.","definition":"Restraint in claiming superiority, praising oneself or drawing attention to one''s virtues.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Readily expresses a high opinion of oneself.\nMay emphasise personal virtues.\nCan make superiority claims.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Avoids claiming superiority.\nIs less inclined to boast.\nMay downplay personal virtues.","anchor_low":"Readily expresses a high opinion of oneself.","anchor_high":"Avoids claiming superiority.","strength_commentary":"Visible self-advocacy can communicate achievements; modesty can leave room for others. This facet does not establish accurate self-insight or confidence.","development_suggestion":"Describe achievements with evidence while recognising the contributions and strengths of others.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"d96f55fa-655f-53e7-afdb-147b7215d6b8","slug":"ipip-neo-120-johnson-2014-a6-sympathy","name":"Compassion","description":"A6 — Compassion and concern for people experiencing hardship or disadvantage.","definition":"Compassion and concern for people experiencing hardship or disadvantage.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Maintains more distance from others'' difficulties.\nMay give hardship less attention.\nCan prefer to avoid distressing concerns.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Feels concern for people facing hardship.\nResponds with compassion.\nOften attends to others'' difficulties.","anchor_low":"Maintains more distance from others'' difficulties.","anchor_high":"Feels concern for people facing hardship.","strength_commentary":"Emotional distance can help maintain boundaries; compassion can draw attention to unmet needs. Neither alone establishes sound decisions or effective assistance.","development_suggestion":"Consider others'' needs alongside evidence, fairness and the practical consequences of a response.","dimension_id":"37eaeec8-c545-5484-adeb-7c39141ecf85","composition_locked":true,"is_match_eligible":false},{"id":"ad1aa223-9920-5d90-a0a6-f4c7a7c72818","slug":"ipip-neo-120-johnson-2014-c1-self-efficacy","name":"Perceived Competence","description":"C1 — Belief in one''s effectiveness at completing tasks and handling practical demands. This is perceived competence, not independently demonstrated ability.","definition":"Belief in one''s effectiveness at completing tasks and handling practical demands. This is perceived competence, not independently demonstrated ability.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Reports less confidence in task effectiveness.\nMay doubt how well tasks will be handled.\nCan feel less certain about getting things done.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Reports confidence in completing tasks.\nFeels able to handle demands.\nUsually expects to know how to get things done.","anchor_low":"Reports less confidence in task effectiveness.","anchor_high":"Reports confidence in completing tasks.","strength_commentary":"Confidence can support willingness to act; doubt can encourage checking or assistance. This facet measures perceived effectiveness rather than demonstrated competence.","development_suggestion":"Compare confidence with task evidence and identify where practice, feedback or help would improve calibration.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false},{"id":"6ec6d894-8648-54bf-ae0b-d689b722632e","slug":"ipip-neo-120-johnson-2014-c2-orderliness","name":"Orderliness","description":"C2 — Preference for tidiness, organisation and returning belongings to their proper place.","definition":"Preference for tidiness, organisation and returning belongings to their proper place.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"Is less concerned with tidiness.\nMay leave belongings out of place.\nCan prefer a less orderly environment.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually keeps things tidy.\nReturns belongings to their place.\nPrefers an orderly environment.","anchor_low":"Is less concerned with tidiness.","anchor_high":"Usually keeps things tidy.","strength_commentary":"An orderly environment can make retrieval and routines easier; less concern with tidiness may suit some flexible settings. This facet does not establish planning or management skill.","development_suggestion":"Use enough structure to make work manageable without adding organisation that serves little purpose.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false},{"id":"53f6532e-01a9-518a-a863-938170083ace","slug":"ipip-neo-120-johnson-2014-c3-dutifulness","name":"Dependability","description":"C3 — Reported commitment to promises, truthfulness and following rules.","definition":"Reported commitment to promises, truthfulness and following rules.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May treat commitments or rules more flexibly.\nCan report breaking promises.\nMay be less consistent about truthfulness.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually reports keeping promises.\nTakes rules and commitments seriously.\nEndorses telling the truth.","anchor_low":"May treat commitments or rules more flexibly.","anchor_high":"Usually reports keeping promises.","strength_commentary":"Commitment can support reliability. Whether a rule should be followed or challenged requires judgement beyond this self-report facet.","development_suggestion":"Make commitments explicitly, raise difficulties early and explain any necessary challenge to an inappropriate rule.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false},{"id":"2297e64d-7e0f-5567-aab5-64e0a1b74487","slug":"ipip-neo-120-johnson-2014-c4-achievement-striving","name":"Achievement Striving","description":"C4 — Willingness to work hard, exceed requirements and invest effort in achievement.","definition":"Willingness to work hard, exceed requirements and invest effort in achievement.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May be satisfied with meeting minimum requirements.\nOften invests less additional effort.\nCan place less emphasis on demanding achievement.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often works hard.\nTries to exceed expectations.\nInvests effort in achieving more.","anchor_low":"May be satisfied with meeting minimum requirements.","anchor_high":"Often works hard.","strength_commentary":"A measured level of striving can protect other priorities; strong striving can sustain demanding goals. Actual outcomes and the value of the goals require separate evidence.","development_suggestion":"Choose goals deliberately and check that effort remains proportionate to priorities and available capacity.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false},{"id":"f279054d-6129-50b7-ab9e-03de6a5b21fa","slug":"ipip-neo-120-johnson-2014-c5-self-discipline","name":"Self-Discipline","description":"C5 — Inclination to start tasks, stay prepared and carry plans through rather than delay or waste time.","definition":"Inclination to start tasks, stay prepared and carry plans through rather than delay or waste time.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May delay starting tasks.\nCan find follow-through difficult.\nMay spend time on competing distractions.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Often starts tasks readily.\nPrepares for what needs doing.\nUsually carries out plans.","anchor_low":"May delay starting tasks.","anchor_high":"Often starts tasks readily.","strength_commentary":"Sustained task focus can support completion; willingness to pause can sometimes allow reprioritisation. The facet does not establish whether a task should be continued.","development_suggestion":"Identify the next useful action and review whether persistence or a deliberate change of plan is needed.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false},{"id":"9ab613c5-a54d-5a94-a389-2350f6cdc164","slug":"ipip-neo-120-johnson-2014-c6-cautiousness","name":"Deliberation","description":"C6 — Tendency to deliberate before acting rather than rush into decisions.","definition":"Tendency to deliberate before acting rather than rush into decisions.","is_active":false,"source_id":"891763cf-96e3-5ed1-ac86-23bc6cd48d79","indicators_low":"May act quickly with limited advance thought.\nCan make spontaneous decisions.\nMay rush into action.","indicators_mid":"Expression can vary by context; examine examples of both ends.","indicators_high":"Usually thinks before acting.\nIs less inclined to make rash decisions.\nOften considers actions in advance.","anchor_low":"May act quickly with limited advance thought.","anchor_high":"Usually thinks before acting.","strength_commentary":"Speed can matter when action is urgent; deliberation can help examine consequences. Neither end establishes decision quality or an appropriate appetite for risk.","development_suggestion":"Match the amount of deliberation to the stakes, time available and reversibility of the decision.","dimension_id":"96f9a279-2430-5bbd-a852-d150f2996afd","composition_locked":true,"is_match_eligible":false}],"factor_constructs":[{"id":"dfd6ad88-0c18-5642-adba-f0eb65d3926f","factor_id":"fd95d192-570f-5449-aa8d-cc32ff5ac13a","construct_id":"a194892c-2d9c-5ccf-a6f0-bf86d6fe86e5","weight":1,"display_order":0},{"id":"b2621ec8-d331-5aa0-ab69-60bad1701b5a","factor_id":"719b6184-0aab-5120-a543-6ea246c75614","construct_id":"19715e40-733c-5b82-a9a8-bde1eeb5b74d","weight":1,"display_order":0},{"id":"1137e9fe-8ef9-53fb-a8ce-5671f8431106","factor_id":"e7d10d8a-8010-5600-ac49-10d8a8e98b40","construct_id":"155e370a-1546-55b4-a616-393b597562a4","weight":1,"display_order":0},{"id":"e7b4eefc-7a6f-5c39-aff4-f61e7790c3d8","factor_id":"79406023-774e-57c5-a9e8-2b7ff83073d4","construct_id":"ce398614-b3e2-57f1-a872-f7064a00cf42","weight":1,"display_order":0},{"id":"f295fa23-5983-5780-a832-c737165e9de8","factor_id":"837da813-c25c-5684-a99c-722c4f4e43a5","construct_id":"de5e5ade-9bf9-5e5c-a260-795621cfc225","weight":1,"display_order":0},{"id":"9e679b7d-782a-5bd2-adb3-7415f6f68d15","factor_id":"01b3745a-9d63-58d8-ac8a-e2b1b0ca224d","construct_id":"43e29f79-221f-5a76-ae27-3b2da4c67e9d","weight":1,"display_order":0},{"id":"dc4c1316-a499-55b3-a3d2-1f7b7a41bb8c","factor_id":"d61dde63-45eb-53c2-a896-4e232236ffc9","construct_id":"fa2e986b-788c-5d9b-a591-8817ad53a853","weight":1,"display_order":0},{"id":"674d68d7-230e-58f1-ad4a-c492fc6f27f8","factor_id":"fcddb27a-cc2a-50c4-acb0-afb324b0808f","construct_id":"b478a98a-65ed-55dd-a2a5-0cf242c075f6","weight":1,"display_order":0},{"id":"afca95de-6115-501