BEGIN
  FOR tbl IN SELECT unnest(ARRAY['content_sources','response_formats','dimensions','constructs','factors','factor_constructs','items','assessments','assessment_factors','assessment_sections','assessment_section_items']) LOOP
    FOR expected IN SELECT value FROM jsonb_array_elements(config->'rows'->tbl) LOOP
      EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id=$1',tbl) INTO actual USING (expected->>'id')::uuid;
      IF actual IS NOT NULL THEN
        IF NOT actual @> expected THEN RAISE EXCEPTION 'IPIP import collision in % at %',tbl,expected->>'id'; END IF;
      ELSE
        SELECT string_agg(format('%I',key),',') INTO columns FROM jsonb_object_keys(expected) key;
        EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1)',tbl,columns,columns,tbl) USING expected;
      END IF;
    END LOOP;
  END LOOP;
  INSERT INTO public.standardized_assessment_forms(assessment_id,instrument_id,definition) VALUES ((config->>'assessmentId')::uuid,config->>'instrumentId',config) ON CONFLICT (assessment_id) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM public.standardized_assessment_forms WHERE assessment_id=(config->>'assessmentId')::uuid AND definition=config) THEN RAISE EXCEPTION 'IPIP binding collision'; END IF;
END $import$;
COMMIT;
